-- 20260619000001 — engine_params v9: rep-window prescription (doc 13 + §9)
--
-- Activates the doc 13 model: the prescribed weight is chosen so reps land in a
-- per-goal productive window at the week's target RIR (from the recency-weighted
-- strength anchor), reps are graded on RIR (overshooting intensity holds, never
-- regresses), and the anchor is `session_best` (the recency-weighted best set,
-- averaged across that set's session — robust to a lone blow-out set). Strength
-- vs hypertrophy now carry distinct rep windows (3–5 vs 8–12).
--
-- The behavior is param-gated (doc 13 decision 8): `weight_selection` and
-- `grading` flip the engine between the new rep-window/RIR path and the legacy
-- increment/rep-count path, so rolling back is an `engine_params` activation, not
-- a redeploy. Both paths live in code; the increment path is byte-for-byte the v8
-- behavior. The schema gained these fields with legacy-valued defaults, so every
-- pre-v9 row still parses to the increment path — only this active row turns the
-- new model on.
--
-- Adding the rep-window block changes the schema *shape*, so schema_version bumps
-- to 4 (params-provenance.ts). This seeds v9 as a fully materialized v4 snapshot
-- with its canonical sha256 hash (generated by the app's own
-- `engineParamsSchema.parse()` + `hashParams()`), so it replays exactly. v8 and
-- earlier predate the rep-window fields, so under schema v4 their stored bytes are
-- no longer byte-complete materializations and are flagged non-replayable.

-- single-active invariant: deactivate the current active version before insert.
update public.engine_params set is_active = false where is_active = true;

insert into public.engine_params (version, params, is_active, notes, schema_version, params_hash, code_sha, is_replayable)
