-- versions <= 8 predate the rep-window fields, so under schema v4 their stored
-- bytes are no longer byte-complete materializations; flag them non-replayable to
-- match what the reader (resolveProvenance, current schema) now computes.
update public.engine_params set is_replayable = false where version <= 8;
